-- Baseline of the public schema, generated by scripts/dump-schema.ts from the live project. Later migrations go on top of it.
-- Not in here (it is data or secret): the rows, auth users, storage files, and the cron jobs' secrets (see docs/DEPLOY.md).
set check_function_bodies = off;

-- Extensions
create extension if not exists pgcrypto with schema extensions;
create extension if not exists "uuid-ossp" with schema extensions;
create extension if not exists pg_net with schema extensions;
create extension if not exists pg_cron;

