-- Functions
CREATE OR REPLACE FUNCTION public.adopt_guest(guest uuid, owner uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  moved jsonb := '{}'::jsonb;
  n int;
begin
  if guest = owner then
    raise exception 'same account';
  end if;
  if not exists (select 1 from guest_accounts where user_id = guest and merged_into is null) then
    raise exception 'not an unmerged guest account';
  end if;

  if not exists (select 1 from profiles where user_id = owner) then
    update profiles set user_id = owner where user_id = guest;
    get diagnostics n = row_count;
    moved := moved || jsonb_build_object('profile', n);
  else
    moved := moved || jsonb_build_object('profile', 0, 'kept_existing_profile', true);
  end if;

  update push_subscriptions set user_id = owner where user_id = guest;
  get diagnostics n = row_count; moved := moved || jsonb_build_object('phones', n);

  update applications set user_id = owner where user_id = guest;
  get diagnostics n = row_count; moved := moved || jsonb_build_object('applications', n);

  update linkedin_imports set user_id = owner where user_id = guest;

  update profile_facts f set user_id = owner where f.user_id = guest
    and not exists (select 1 from profile_facts o where o.user_id = owner and o.item_hash = f.item_hash);
  update strength_cache s set user_id = owner where s.user_id = guest
    and not exists (select 1 from strength_cache o where o.user_id = owner and o.cv_hash = s.cv_hash and o.posting_id = s.posting_id);

  update guest_accounts set merged_into = owner, merged_at = now() where user_id = guest;

  return moved;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.adopt_guest_documents(guest uuid, owner uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  room int;
  n int := 0;
begin
  select greatest(0, 5 - count(*)) into room from documents where user_id = owner;

  with picked as (
    select g.id
    from documents g
    where g.user_id = guest
      and not exists (select 1 from documents o where o.user_id = owner and o.content_hash = g.content_hash)
      and not exists (select 1 from documents o where o.user_id = owner and o.kind = g.kind and lower(btrim(o.name)) = lower(btrim(g.name)))
    order by g.created_at
    limit room
  ), moved as (
    update documents d set user_id = owner, is_main = (d.is_main and not exists (select 1 from documents m where m.user_id = owner and m.is_main))
    from picked p where d.id = p.id
    returning d.id
  )
  select count(*) into n from moved;

  update job_documents j set user_id = owner
  where j.user_id = guest
    and exists (select 1 from documents d where d.id = j.document_id and d.user_id = owner)
    and not exists (select 1 from job_documents o where o.user_id = owner and o.posting_id = j.posting_id and o.kind = j.kind);

  return n;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.answer_application_questions(p_posting_id text, p_answers jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null then raise exception 'Sign in first.' using errcode='42501'; end if;
 perform public.answer_application_questions_for(auth.uid(),p_posting_id,p_answers);
end $function$
;
CREATE OR REPLACE FUNCTION public.answer_application_questions_for(p_user uuid, p_posting_id text, p_answers jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare prompt public.application_prompts; q jsonb; value text; item record;
begin
 if p_user is null then raise exception 'Sign in first.' using errcode='42501'; end if;
 if p_answers is null or jsonb_typeof(p_answers)<>'object' or p_answers='{}'::jsonb then raise exception 'Send answers by question.'; end if;
 select * into prompt from public.application_prompts where user_id=p_user and posting_id=p_posting_id and updated_at>now()-interval '30 minutes' for update;
 if not found then raise exception 'These questions are no longer current. Wait for the desktop to refresh.'; end if;
 for item in select * from jsonb_each_text(p_answers) loop
  select x into q from jsonb_array_elements(prompt.questions) x where x->>'key'=item.key;
  if q is null then raise exception 'The form changed. Refresh the questions first.'; end if;
  value:=btrim(item.value);
  if value is null or length(value)<1 or length(value)>1000 then raise exception 'Enter an answer between 1 and 1000 characters.'; end if;
  if q->>'kind'='number' and value !~ '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)$' then raise exception 'Enter a number.'; end if;
  if q->>'kind' in ('radio','select') and not ((q->'options') ? value) then raise exception 'Choose an option shown by the form.'; end if;
  insert into public.application_questions(user_id,question_key,question,answer) values(p_user,q->>'key',q->>'label',value)
  on conflict(user_id,question_key) do update set answer=excluded.answer,question=excluded.question,updated_at=now();
 end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.applications_outcome()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'DELETE' then
    delete from public.chance_snapshots where user_id = old.user_id and posting_id = old.posting_id;

    return old;
  end if;
  -- An interview stays an interview when it moves on to an offer; a later "rejected" after an interview does not erase it.
  update public.chance_snapshots s
     set outcome = coalesce(public.stage_outcome(new.stage), case when new.stage = 'applied' then null else s.outcome end),
         outcome_on = case when new.stage = 'applied' then null when public.stage_outcome(new.stage) is null then s.outcome_on else coalesce(s.outcome_on, current_date) end
   where s.user_id = new.user_id and s.posting_id = new.posting_id
     and (s.outcome is distinct from 'interview' or new.stage not in ('rejected', 'no_reply'));

  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.cancel_application(p_id uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.application_runs set status='cancelled',message='Preparation cancelled.',updated_at=now() where id=p_id and user_id=auth.uid() and status in ('queued','filling','needs_input','ready');
$function$
;
CREATE OR REPLACE FUNCTION public.close_expired_postings()
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare
  r record;
  n integer := 0;
begin
  for r in
    select id, left(valid_through, 10) as d from public.postings
    where closed_at is null and valid_through ~ '^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])'
  loop
    begin
      if r.d::date < current_date then
        update public.postings set closed_at = now(), last_checked = now() where id = r.id and closed_at is null;
        insert into public.postings_audit_log (id, col, old_value, new_value, reason, at)
        values (r.id, 'closed_at', null, 'closed', 'The posting''s own deadline (' || r.d || ') has passed. Closed automatically by close_expired_postings(), hourly.', now());
        n := n + 1;
      end if;
    exception when others then
      continue; -- an impossible date such as 30 February: leave the posting alone
    end;
  end loop;
  return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.company_research(p_employer text, p_display text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select r.data from employer_research r
  where lower(r.employer) in (lower(trim(p_employer)), lower(trim(coalesce(p_display, ''))))
     or lower(r.display) in (lower(trim(p_employer)), lower(trim(coalesce(p_display, ''))))
  order by (r.employer = p_employer) desc
  limit 1;
$function$
;
CREATE OR REPLACE FUNCTION public.create_extension_key()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  k text;
begin
  if auth.uid() is null then
    raise exception 'Sign in first.' using errcode = '42501';
  end if;
  k := 'oddsx_' || encode(extensions.gen_random_bytes(24), 'hex');
  insert into public.extension_keys (user_id, key_hash, hint)
  values (auth.uid(), encode(extensions.digest(k, 'sha256'), 'hex'), right(k, 4))
  on conflict (user_id) do update set key_hash = excluded.key_hash, hint = excluded.hint, created_at = now(), last_used_at = null;

  return k;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.create_mcp_key()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  k text;
begin
  if auth.uid() is null then
    raise exception 'Sign in first.' using errcode = '42501';
  end if;
  k := 'odds_' || encode(extensions.gen_random_bytes(24), 'hex');
  insert into public.mcp_keys (user_id, key_hash, hint)
  values (auth.uid(), encode(extensions.digest(k, 'sha256'), 'hex'), right(k, 4))
  on conflict (user_id) do update set key_hash = excluded.key_hash, hint = excluded.hint, created_at = now(), last_used_at = null;

  return k;
end;
$function$
