CREATE OR REPLACE FUNCTION public.documents_touch()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.drive_cancel_open_commands(p_run uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  update public.drive_commands
    set status = 'cancelled',
        result = coalesce(result, '{}'::jsonb) || jsonb_build_object('ok', false, 'cancelled', true, 'error', 'run ended'),
        done_at = coalesce(done_at, now())
    where run_id = p_run and status in ('queued', 'taken');
  get diagnostics n = row_count;
  return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.drive_control(p_run uuid, p_action text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if p_action = 'stop' then
    update drive_runs set status = 'stopped', reason = null, resume_pending = false, message = 'You stopped Broods on this application.',
        agent_finished_at = coalesce(agent_finished_at, now()), updated_at = now()
      where id = p_run and user_id = auth.uid() and status not in ('stopped', 'submitted');
    get diagnostics n = row_count;
    if n > 0 then perform public.drive_cancel_open_commands(p_run); end if;
  elsif p_action = 'continue' then
    update drive_runs set status = 'running', reason = null, resume_pending = true, message = null, last_note = 'Carrying on where it stopped…',
        expires_at = now() + interval '30 minutes', agent_finished_at = null, fill_ended_at = null, updated_at = now()
      where id = p_run and user_id = auth.uid() and status <> 'submitted';
    get diagnostics n = row_count;
  elsif p_action = 'sent' then
    update drive_runs set status = 'submitted', resume_pending = false, message = 'You sent it.', updated_at = now()
      where id = p_run and user_id = auth.uid();
    get diagnostics n = row_count;
    if n > 0 then perform public.drive_cancel_open_commands(p_run); end if;
  else
    return 'unknown';
  end if;
  return case when n > 0 then 'ok' else 'none' end;
end $function$
;
CREATE OR REPLACE FUNCTION public.guard_job_relationship()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if new.role='hiring_manager' and not coalesce(new.relationship_verified and new.evidence_url ~ '^https://' and length(btrim(new.evidence_quote))>=20 and new.verified_at is not null,false) then
  new.role:='department_manager';
  new.relationship_verified:=false;
 end if;
 return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.guard_person_relationship()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if new.jev->>'role'='hiring_manager' then
  new.jev:=new.jev||jsonb_build_object('role','department_manager','hiring_manager_verified',false,'relationship_basis','title_only');
 end if;
 return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.job_company(p_employer text, p_display text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with keys as (
    select distinct lower(trim(k)) as k from unnest(array[p_employer, p_display]) as k where coalesce(trim(k), '') <> ''
  ),
  facts as (
    select f.* from employer_facts f where lower(f.employer) in (select k from keys) order by (f.employer = p_employer) desc, f.fetched_at desc nulls last limit 1
  ),
  research as (
    select r.data from employer_research r where lower(r.employer) in (select k from keys) or lower(r.display) in (select k from keys) limit 1
  ),
  gd as (
    select g.* from employer_glassdoor g where lower(g.employer) in (select k from keys) order by g.review_count desc nulls last limit 1
  ),
  -- The same review can be stored under two spellings of the employer: kept once.
  rv as (
    select distinct on (r.title, r.review_date, left(coalesce(r.pros, ''), 80)) r.*
    from employer_glassdoor_reviews r where lower(r.employer) in (select k from keys)
    order by r.title, r.review_date, left(coalesce(r.pros, ''), 80), r.read_on desc nulls last
  )
  select jsonb_build_object(
    'research', (select data from research),
    'facts', (select jsonb_build_object(
      'name', name, 'tagline', tagline, 'description', description, 'website', website, 'linkedin', linkedin_url,
      'founded', founded_year, 'employees', employees, 'employeeRange', employee_range, 'followers', followers,
      'type', company_type, 'headquarters', headquarters, 'locations', locations, 'industry', linkedin_industry,
      'specialities', specialities, 'topSchools', top_schools, 'topFunctions', top_functions, 'topFields', top_fields,
      'readOn', fetched_at) from facts),
    'glassdoor', (select jsonb_build_object(
      'url', glassdoor_url, 'rating', rating, 'reviews', review_count, 'recommendPct', recommend_pct,
      'ceo', ceo_name, 'ceoApprovalPct', ceo_approval_pct, 'readOn', read_on) from gd),
    'reviewStats', (select case when count(*) = 0 then null else jsonb_build_object(
      'count', count(*),
      'overall', round(avg(overall), 1), 'culture', round(avg(rating_culture), 1), 'balance', round(avg(rating_balance), 1),
      'career', round(avg(rating_career), 1), 'pay', round(avg(rating_pay), 1), 'management', round(avg(rating_management), 1),
      'diversity', round(avg(rating_diversity), 1),
      'recommendPct', round(100.0 * count(*) filter (where recommend = 'yes') / nullif(count(*) filter (where recommend in ('yes', 'no')), 0)),
      'newest', max(review_date), 'oldest', min(review_date)) end from rv),
    'money', (select coalesce(jsonb_agg(jsonb_build_object('kind', kind, 'amount', amount, 'currency', currency, 'year', year, 'source', source) order by year desc nulls last), '[]'::jsonb)
      from employer_money m where lower(m.employer) in (select k from keys)),
    'news', (select coalesce(jsonb_agg(jsonb_build_object('title', title, 'url', url, 'site', site, 'date', published) order by published desc nulls last), '[]'::jsonb)
      from (select distinct on (n.url) n.* from employer_news n where lower(n.employer) in (select k from keys) order by n.url, n.published desc) n),
    'reviews', (select coalesce(jsonb_agg(x order by (x->>'date') desc nulls last), '[]'::jsonb) from (
      select jsonb_build_object('date', review_date, 'title', title, 'role', role, 'status', status, 'place', place,
        'overall', overall, 'recommend', recommend, 'pros', pros, 'cons', cons) as x
      from rv order by review_date desc nulls last limit 30) t)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.job_documents_check()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if not exists (select 1 from public.documents d where d.id = new.document_id and d.user_id = new.user_id and d.kind = new.kind) then
    raise exception 'that document is not yours or is the wrong kind';
  end if;
  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.job_successful_candidates(p_posting text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    return '[]'::jsonb;
  end if;

  return public.job_successful_candidates_inner(p_posting);
end;
$function$
;
CREATE OR REPLACE FUNCTION public.job_successful_candidates_inner(p_posting text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(x order by (x->>'status') = 'exact' desc, (x->>'confidence')::numeric desc nulls last), '[]'::jsonb)
  from (
    select distinct on (cp.id) jsonb_build_object(
      'id', cp.id,
      'name', cp.full_name,
      'headline', cp.headline,
      'currentPosition', cp.current_position,
      'location', cp.public_location,
      'avatar', case when cp.avatar_status = 'available' then cp.avatar_url end,
      'linkedin', cp.canonical_linkedin_url,
      'status', e.status,
      'confidence', e.confidence,
      'employerMatch', e.employer_match,
      'levelMatch', e.level_match,
      'experience', (select coalesce(jsonb_agg(jsonb_build_object('employer', x.employer, 'title', x.title, 'start', x.start_date, 'end', x.end_date,
          'current', x.is_current, 'type', x.experience_type, 'description', x.description) order by x.is_current desc nulls last, x.start_date desc nulls last), '[]'::jsonb)
        from candidate_experience x where x.candidate_profile_id = cp.id),
      'education', (select coalesce(jsonb_agg(jsonb_build_object('school', x.school, 'degree', x.degree, 'field', x.field, 'start', x.start_date, 'end', x.end_date)
          order by x.end_date desc nulls last), '[]'::jsonb)
        from candidate_education x where x.candidate_profile_id = cp.id)
    ) as x
    from job_candidate_evidence e
    join candidate_profiles cp on cp.id = e.candidate_profile_id
    where e.posting_id = p_posting and e.validation_status = 'validated' and e.status in ('exact', 'adjacent')
    order by cp.id, (e.status = 'exact') desc, e.confidence desc nulls last
  ) t;
$function$
;
CREATE OR REPLACE FUNCTION public.outreach_drafts_limit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if (select count(*) from public.outreach_drafts where user_id = new.user_id) >= 300 then
    raise exception 'outreach limit' using errcode = 'P0001', hint = 'Three hundred drafts are kept. Delete some in odds first.';
  end if;
  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.poll_application(p_user uuid, p_device uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare task public.application_runs;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
  insert into public.application_desktops(user_id,device_id) values(p_user,p_device) on conflict(user_id,device_id) do update set last_seen_at=now();
  update public.application_runs set status='failed',message='Preparation expired. Start again on your desktop.',updated_at=now() where user_id=p_user and status in ('queued','filling') and expires_at<now();
  select * into task from public.application_runs where user_id=p_user and status in ('queued','filling','needs_input','ready') order by created_at limit 1 for update;
  if not found then return null; end if;
  if task.status='queued' then
    update public.application_runs set status='filling',message='Opening the application on your desktop.',device_id=p_device,updated_at=now() where id=task.id returning * into task;
  end if;
  if task.device_id<>p_device then return null; end if;
  return to_jsonb(task);
end $function$
;
CREATE OR REPLACE FUNCTION public.poll_applications(p_user uuid, p_device uuid, p_known uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare task public.application_runs; states jsonb;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
  insert into public.application_desktops(user_id,device_id) values(p_user,p_device) on conflict(user_id,device_id) do update set last_seen_at=now();
  update public.application_runs set status='failed',message='Preparation expired. Your open application remains on your desktop.',updated_at=now() where user_id=p_user and status in ('queued','filling') and expires_at<now();
  select coalesce(jsonb_agg(jsonb_build_object('id',id,'status',status,'resume_version',resume_version)),'[]'::jsonb) into states from public.application_runs where user_id=p_user and device_id=p_device and id=any(p_known);
  select * into task from public.application_runs where user_id=p_user and expires_at>now() and (status='queued' or (status='filling' and device_id=p_device and not(id=any(p_known)))) order by (status='queued') desc,created_at limit 1 for update;
  if found and task.status='queued' then
    update public.application_runs set status='filling',message='Opening this application in its own desktop tab.',device_id=p_device,updated_at=now() where id=task.id returning * into task;
  end if;
  return jsonb_build_object('task',case when task.id is null then null else to_jsonb(task) end,'runs',states);
end $function$
;
CREATE OR REPLACE FUNCTION public.record_site_lesson(p_run uuid, p_host text, p_ats text, p_lesson jsonb, p_outcome text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  fp text := md5(p_lesson::text);
  inserted_id bigint;
  target record;
  book jsonb;
  item jsonb;
  ids jsonb;
  n integer;
begin
  insert into site_lessons(run_id,host,ats,kind,lesson,fingerprint,outcome)
  values(p_run,p_host,p_ats,p_lesson->>'kind',p_lesson,fp,p_outcome)
  on conflict(run_id,host,fingerprint) do nothing returning id into inserted_id;
  if inserted_id is null then return; end if;
  for target in select 'host'::text as scope,p_host as key union all select 'ats',p_ats where p_ats is not null loop
    insert into site_playbooks(scope,key) values(target.scope,target.key) on conflict do nothing;
    select lessons into book from site_playbooks where scope=target.scope and key=target.key for update;
    item := coalesce(book->fp,jsonb_build_object('lesson',p_lesson,'successes',0,'failures',0,'source_runs','[]'::jsonb));
    ids := coalesce(item->'source_runs','[]'::jsonb);
    if not ids @> to_jsonb(array[p_run::text]) then ids := ids || to_jsonb(p_run::text); end if;
    item := jsonb_set(item,'{source_runs}',ids);
    if p_outcome='success' then
      n := coalesce((item->>'successes')::integer,0)+1;
      item := item || jsonb_build_object('successes',n,'last_success',now());
    else
      item := item || jsonb_build_object('failures',coalesce((item->>'failures')::integer,0)+1,'last_failure',now());
    end if;
    book := jsonb_set(book,array[fp],item);
    update site_playbooks set lessons=book, recipes=(select coalesce(jsonb_agg(value),'[]') from jsonb_each(book) where (value->>'failures')::int<3 and (not value ? 'last_failure' or (value->>'last_failure')::timestamptz < now()-interval '14 days') and (((value->>'successes')::int>=5 and (value->'lesson'->>'kind') in ('opener','skip_dialog')) or ((value->>'successes')::int>=3 and (value->'lesson'->>'kind')='mapping' and value->'lesson' ? 'label'))),updated_at=now() where scope=target.scope and key=target.key;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.record_site_tactic(p_platform text, p_kind text, p_tactic text, p_ok boolean)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  insert into public.site_tactics(platform, field_kind, tactic, successes, failures)
  values (left(p_platform, 120), left(p_kind, 40), left(p_tactic, 40), case when p_ok then 1 else 0 end, case when p_ok then 0 else 1 end)
  on conflict (platform, field_kind, tactic) do update
    set successes = site_tactics.successes + excluded.successes,
        failures = site_tactics.failures + excluded.failures,
        updated_at = now();
$function$
;
CREATE OR REPLACE FUNCTION public.report_application(p_user uuid, p_device uuid, p_id uuid, p_status text, p_message text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_status not in ('filling','needs_input','ready','submitted','failed') then raise exception 'Invalid application state.'; end if;
  update public.application_runs set status=p_status,message=left(p_message,500),updated_at=now() where id=p_id and user_id=p_user and device_id=p_device and status in ('filling','needs_input','ready') and expires_at>now();
end $function$
;
CREATE OR REPLACE FUNCTION public.revoke_extension_key()
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  delete from public.extension_keys where user_id = auth.uid();
$function$
;
CREATE OR REPLACE FUNCTION public.revoke_mcp_key()
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  delete from public.mcp_keys where user_id = auth.uid();
$function$
;
CREATE OR REPLACE FUNCTION public.set_main_document(doc uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
begin
  if not exists (select 1 from public.documents where id = doc and user_id = auth.uid() and kind = 'cv') then
    raise exception 'not one of your CVs';
  end if;
  update public.documents set is_main = false where user_id = auth.uid() and is_main and id <> doc;
  update public.documents set is_main = true where id = doc and user_id = auth.uid();
end;
$function$
;
CREATE OR REPLACE FUNCTION public.stage_outcome(stage text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case stage
    when 'interview' then 'interview'
    when 'offer' then 'interview'
    when 'hired' then 'interview'
    when 'rejected' then 'rejected'
    when 'no_reply' then 'no_reply'
    else null  -- applied, withdrawn: not an answer
  end;
$function$
;

