create table if not exists public."postings" (
  id text not null,
  employer text,
  employer_display text,
  ats text,
  source text,
  title text,
  region text,
  cat text,
  cbs_group text,
  url text,
  ind_sponsor boolean,
  ind_sponsor_name text,
  years_min integer,
  dutch_required boolean,
  visa_mention boolean,
  junior_title boolean,
  degree_asked text,
  skills text[],
  pay_posted text,
  applicants integer,
  applicants_text text,
  valid_through text,
  seniority text,
  body text,
  posted_at text,
  days_open integer,
  freshness_state text,
  fetched_at date,
  first_seen date default CURRENT_DATE,
  last_seen date default CURRENT_DATE,
  level text,
  student_fit boolean default false,
  english boolean,
  restricted boolean default false,
  screening boolean,
  nationality_cond boolean,
  scale text,
  title_clean text,
  level_jev text,
  level_conf real,
  usable real,
  industry text,
  workplace text,
  job_type text,
  dutch_jev real,
  family text,
  requirements jsonb,
  last_checked timestamp with time zone,
  miss_count integer default 0 not null,
  closed_at timestamp with time zone,
  posted_on date,
  degree_asked_raw text,
  skill_tiers jsonb,
  enrollment text,
  read_by text,
  role_kind text,
  work_signals text[] generated always as (array_remove(ARRAY[
CASE
    WHEN (body ~~* ANY (ARRAY['%hybrid%'::text, '%hybride%'::text, '%work from home%'::text, '%thuiswerken%'::text, '%partly remote%'::text, '%remote work%'::text])) THEN 'hybrid'::text
    ELSE NULL::text
END,
CASE
    WHEN (body ~~* ANY (ARRAY['%fully remote%'::text, '%100% remote%'::text, '%remote-first%'::text, '%remote first%'::text, '%remote position%'::text, '%remote role%'::text, '%work remotely%'::text, '%volledig remote%'::text])) THEN 'remote'::text
    ELSE NULL::text
END,
CASE
    WHEN (body ~~* ANY (ARRAY['%part-time%'::text, '%part time%'::text, '%parttime%'::text, '%deeltijd%'::text])) THEN 'partTime'::text
    ELSE NULL::text
END,
CASE
    WHEN (body ~~* ANY (ARRAY['%full-time%'::text, '%full time%'::text, '%fulltime%'::text, '%voltijd%'::text, '%40 hours%'::text, '%38 hours%'::text, '%36 hours%'::text, '%40 uur%'::text, '%38 uur%'::text, '%36 uur%'::text])) THEN 'fullTime'::text
    ELSE NULL::text
END,
CASE
    WHEN (body ~~* ANY (ARRAY['%fixed-term%'::text, '%fixed term%'::text, '%freelance%'::text, '%interim%'::text, '%temporary%'::text, '%tijdelijk%'::text, '%bepaalde tijd%'::text, '%zzp%'::text, '%detachering%'::text, '%contractor%'::text])) THEN 'contract'::text
    ELSE NULL::text
END], NULL::text)) stored
);
