-- Functions that use a table's row type
CREATE OR REPLACE FUNCTION public.continue_application(p_posting_id text)
 RETURNS application_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null then raise exception 'Sign in first.' using errcode='42501'; end if;
 return public.continue_application_for(auth.uid(),p_posting_id);
end $function$
;
CREATE OR REPLACE FUNCTION public.continue_application_for(p_user uuid, p_posting_id text)
 RETURNS application_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result public.application_runs;
begin
 if p_user is null then raise exception 'Sign in first.' using errcode='42501'; end if;
 update public.application_runs set resume_version=resume_version+1,expires_at=now()+interval '15 minutes',updated_at=now(),message='Returning to your application on desktop.'
 where user_id=p_user and posting_id=p_posting_id and status in ('filling','needs_input','ready') returning * into result;
 if not found then raise exception 'No active application. Start this job again.'; end if;
 return result;
end $function$
;
CREATE OR REPLACE FUNCTION public.request_application(p_posting_id text)
 RETURNS application_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null then raise exception 'Sign in first.' using errcode='42501'; end if;
 return public.request_application_for(auth.uid(),p_posting_id);
end $function$
;
CREATE OR REPLACE FUNCTION public.request_application_for(p_user uuid, p_posting_id text)
 RETURNS application_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare job_url text; result public.application_runs;
begin
  if p_user is null then raise exception 'Sign in first.' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
  update public.application_runs set status='failed',message='Preparation expired. Your open application remains on your desktop.',updated_at=now() where user_id=p_user and status in ('queued','filling','needs_input','ready') and expires_at<now();
  select * into result from public.application_runs where user_id=p_user and posting_id=p_posting_id and status in ('queued','filling','needs_input','ready') limit 1;
  if found then return result; end if;
  select url into job_url from public.postings where id=p_posting_id and closed_at is null;
  if job_url is null or job_url not like 'https://%' then raise exception 'This job has no available application page.'; end if;
  insert into public.application_runs(user_id,posting_id,url) values(p_user,p_posting_id,job_url) returning * into result;
  return result;
end $function$
;
CREATE OR REPLACE FUNCTION public.save_document(document jsonb, posting text DEFAULT NULL::text)
 RETURNS SETOF documents
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare saved public.documents;
begin
  if auth.uid() is null then raise exception 'Sign in to keep documents.'; end if;
  perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text, 0));
  insert into public.documents (id,user_id,kind,name,file_name,mime,size_bytes,content_hash,body,path,is_main)
  values ((document->>'id')::uuid, auth.uid(), document->>'kind', document->>'name', document->>'file_name',
    document->>'mime', (document->>'size_bytes')::integer, document->>'content_hash', document->>'body',
    document->>'path', document->>'kind' = 'cv' and not exists (select 1 from public.documents where user_id=auth.uid() and is_main))
  returning * into saved;
  if saved.path <> auth.uid()::text || '/' || saved.id::text then raise exception 'Invalid document path'; end if;
  if posting is not null then
    insert into public.job_documents (user_id,posting_id,kind,document_id)
    values (auth.uid(),posting,saved.kind,saved.id)
    on conflict (user_id,posting_id,kind) do update set document_id=excluded.document_id, attached_at=now();
  end if;
  return next saved;
end; $function$
;

