-- Indexes
CREATE UNIQUE INDEX IF NOT EXISTS application_one_active_per_job ON public.application_runs USING btree (user_id, posting_id) WHERE (status = ANY (ARRAY['queued'::text, 'filling'::text, 'needs_input'::text, 'ready'::text]));
CREATE INDEX IF NOT EXISTS application_runs_owner_recent ON public.application_runs USING btree (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS apply_agent_action_patterns_updated ON public.apply_agent_action_patterns USING btree (updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_cedu_candidate_id ON public.candidate_education USING btree (candidate_profile_id);
CREATE INDEX IF NOT EXISTS idx_ce_candidate_id ON public.candidate_experience USING btree (candidate_profile_id);
CREATE INDEX IF NOT EXISTS device_pairs_ip_hour ON public.device_pairs USING btree (ip_hash, created_at DESC);
