CREATE INDEX IF NOT EXISTS linkedin_imports_ip_day ON public.linkedin_imports USING btree (ip_hash, created_at DESC);
CREATE INDEX IF NOT EXISTS linkedin_imports_user_day ON public.linkedin_imports USING btree (user_id, created_at DESC);
