-- Views
create or replace view public.app_jobs with (security_invoker=true) as  WITH base AS (
         SELECT p.id,
            p.employer,
            p.employer_display,
            p.ats,
            p.source,
            p.title,
            p.region,
            p.cat,
            p.cbs_group,
            p.url,
            p.ind_sponsor,
            p.ind_sponsor_name,
            p.years_min,
            p.dutch_required,
            p.visa_mention,
            p.junior_title,
            p.degree_asked,
            p.skills,
            p.pay_posted,
            p.applicants,
            p.applicants_text,
            p.valid_through,
            p.seniority,
            p.posted_at,
            p.days_open,
            p.freshness_state,
            p.fetched_at,
            p.title_clean,
            p.level_jev,
            p.level_conf,
            p.usable,
            p.industry,
            p.workplace,
            p.job_type,
            p.dutch_jev,
            p.family,
            p.closed_at,
            p.last_checked,
            p.posted_on,
                CASE
                    WHEN p.role_kind = ANY (ARRAY['internship'::text, 'working_student'::text]) THEN 'Internship'::text
                    WHEN p.role_kind = ANY (ARRAY['traineeship'::text, 'entry_job'::text]) THEN 'Entry'::text
                    WHEN p.role_kind = 'other'::text THEN 'Not stated'::text
                    WHEN p.title ~* '\y(trainee|traineeship|traineeships)\y'::text AND p.title !~* '\y(intern|internship|stagiair\w*|stage|meewerkstage|werkstudent|working student|graduation)\y'::text THEN 'Entry'::text
                    WHEN p.level_conf >= 0.8::double precision AND (p.level_jev = ANY (ARRAY['internship'::text, 'entry'::text, 'mid'::text, 'senior'::text, 'manager'::text, 'director'::text])) THEN initcap(p.level_jev)
                    WHEN p.title ~* '\y(director|vice president|vp|svp|evp|head of|head,|managing director|general manager|country manager|chief)\y'::text THEN 'Director'::text
                    WHEN p.title ~* '\y(intern|internship|stagiair\w*|stage|meewerkstage)\y'::text OR p.seniority = 'Internship'::text OR p.title ~* '\y(werkstudent|working student)\y'::text THEN 'Internship'::text
                    WHEN p.title ~* '\y(trainee|traineeship)\y'::text THEN 'Entry'::text
                    WHEN p.title ~* '\y(development|graduates?|leadership|talent|rotational|early careers?|future leaders?|young professionals?|fast ?track)\s+(programme|program|track|scheme)\y'::text THEN 'Entry'::text
                    WHEN p.title ~* '\y(senior|sr\.?|staff|principal|architect)\y'::text THEN 'Senior'::text
                    WHEN p.title ~* '(\yteam ?lead|\ytech lead|\ylead |\ymanager\y|\ysupervisor|\yteamleider)'::text THEN
                    CASE
                        WHEN p.title ~* '\y(account|product|project|programm?e?|brand|customer|client|relationship|partner(ship)?|community|content|social media|marketing|campaign|category|channel|sales|business development|change|release|delivery|service|vendor|procurement|implementation|onboarding|portfolio|risk|compliance|quality|solutions?|technical account|engagement)\s+(\w+\s+)?manager\y'::text AND p.title !~* 'team ?lead'::text THEN
                        CASE
                            WHEN p.seniority = 'Mid-Senior level'::text THEN
                            CASE
                                WHEN COALESCE(p.years_min, 0) >= 5 THEN 'Senior'::text
                                ELSE 'Mid'::text
                            END
                            WHEN p.seniority = 'Internship'::text THEN 'Internship'::text
                            WHEN p.seniority = ANY (ARRAY['Entry level'::text, 'Associate'::text]) THEN 'Entry'::text
                            WHEN p.seniority = ANY (ARRAY['Director'::text, 'Executive'::text]) THEN 'Director'::text
                            WHEN p.years_min IS NOT NULL THEN
                            CASE
                                WHEN p.years_min <= 2 THEN 'Entry'::text
                                WHEN p.years_min <= 4 THEN 'Mid'::text
                                ELSE 'Senior'::text
                            END
                            ELSE 'Not stated'::text
                        END
                        ELSE 'Manager'::text
                    END
                    WHEN p.title ~* '\y(junior|jr\.?|graduate|starter|entry|associate|assistant|young professional)\y'::text THEN 'Entry'::text
                    WHEN p.seniority = 'Mid-Senior level'::text THEN
                    CASE
                        WHEN COALESCE(p.years_min, 0) >= 5 THEN 'Senior'::text
                        ELSE 'Mid'::text
                    END
                    WHEN p.seniority = 'Internship'::text THEN 'Internship'::text
                    WHEN p.seniority = ANY (ARRAY['Entry level'::text, 'Associate'::text]) THEN 'Entry'::text
                    WHEN p.seniority = ANY (ARRAY['Director'::text, 'Executive'::text]) THEN 'Director'::text
                    WHEN p.years_min IS NOT NULL THEN
                    CASE
                        WHEN p.years_min <= 2 THEN 'Entry'::text
                        WHEN p.years_min <= 4 THEN 'Mid'::text
                        ELSE 'Senior'::text
                    END
                    ELSE 'Not stated'::text
                END AS level_view
           FROM postings p
          WHERE p.closed_at IS NULL AND (p.usable IS NULL OR p.usable >= 0.5::double precision) AND (p.posted_on IS NULL OR p.posted_on >= (CURRENT_DATE - 180))
        ), keyed AS (
         SELECT b.id,
            b.employer,
            b.employer_display,
            b.ats,
            b.source,
            b.title,
            b.region,
            b.cat,
            b.cbs_group,
            b.url,
            b.ind_sponsor,
            b.ind_sponsor_name,
            b.years_min,
            b.dutch_required,
            b.visa_mention,
            b.junior_title,
            b.degree_asked,
            b.skills,
            b.pay_posted,
            b.applicants,
            b.applicants_text,
            b.valid_through,
            b.seniority,
            b.posted_at,
            b.days_open,
            b.freshness_state,
            b.fetched_at,
            b.title_clean,
            b.level_jev,
            b.level_conf,
            b.usable,
            b.industry,
            b.workplace,
            b.job_type,
            b.dutch_jev,
            b.family,
            b.closed_at,
            b.last_checked,
            b.posted_on,
            b.level_view,
            (((TRIM(BOTH FROM regexp_replace(lower(COALESCE(b.employer_display, ''::text)), '[^a-z0-9]+'::text, ' '::text, 'g'::text)) || '|'::text) || TRIM(BOTH FROM regexp_replace(regexp_replace(lower(COALESCE(b.title, ''::text)), '\m(m ?/ ?f ?/ ?[dx]|f ?/ ?m ?/ ?[dx]|m ?/ ?v ?/ ?x|m ?/ ?w ?/ ?d|h ?/ ?f ?/ ?x|all genders|gender neutral)\M'::text, ' '::text, 'g'::text), '[^a-z0-9]+'::text, ' '::text, 'g'::text))) || '|'::text) || TRIM(BOTH FROM regexp_replace(lower(split_part(split_part(COALESCE(b.region, ''::text), ';'::text, 1), ','::text, 1)), '[^a-z0-9]+'::text, ' '::text, 'g'::text)) AS job_key
           FROM base b
        ), ranked AS (
         SELECT k.id,
            k.employer,
            k.employer_display,
            k.ats,
            k.source,
            k.title,
            k.region,
            k.cat,
            k.cbs_group,
            k.url,
            k.ind_sponsor,
            k.ind_sponsor_name,
            k.years_min,
            k.dutch_required,
            k.visa_mention,
            k.junior_title,
            k.degree_asked,
            k.skills,
            k.pay_posted,
            k.applicants,
            k.applicants_text,
            k.valid_through,
            k.seniority,
            k.posted_at,
            k.days_open,
            k.freshness_state,
            k.fetched_at,
            k.title_clean,
            k.level_jev,
            k.level_conf,
            k.usable,
            k.industry,
            k.workplace,
            k.job_type,
            k.dutch_jev,
            k.family,
            k.closed_at,
            k.last_checked,
            k.posted_on,
            k.level_view,
            k.job_key,
            row_number() OVER (PARTITION BY k.job_key ORDER BY (
                CASE lower(k.ats)
                    WHEN 'workday'::text THEN 0
                    WHEN 'greenhouse'::text THEN 0
                    WHEN 'ashby'::text THEN 0
                    WHEN 'smartrecruiters'::text THEN 0
                    WHEN 'successfactors'::text THEN 0
                    WHEN 'recruitee'::text THEN 0
                    WHEN 'lever'::text THEN 0
                    WHEN 'teamtailor'::text THEN 0
                    WHEN 'personio'::text THEN 0
                    WHEN 'workable'::text THEN 0
                    WHEN 'academictransfer'::text THEN 1
                    WHEN 'magnet.me'::text THEN 2
                    WHEN 'indeed'::text THEN 3
                    WHEN 'glassdoor'::text THEN 4
                    ELSE 5
                END), k.posted_on DESC NULLS LAST, k.id) AS pick_rank
           FROM keyed k
        )
 SELECT r.id,
    r.employer,
    r.employer_display,
    r.ats,
    r.source,
    r.title,
    r.region,
    r.cat,
    r.cbs_group,
    r.url,
    r.ind_sponsor,
    r.ind_sponsor_name,
    r.years_min,
    r.dutch_required,
    r.visa_mention,
    r.junior_title,
    r.degree_asked,
    r.skills,
    r.pay_posted,
    r.applicants,
    r.applicants_text,
    r.valid_through,
    r.seniority,
    r.posted_at,
    r.days_open,
    r.freshness_state,
    r.fetched_at,
    r.title_clean,
    r.level_jev,
    r.level_conf,
    r.usable,
    r.industry,
    r.workplace,
    r.job_type,
    r.dutch_jev,
    r.family,
    r.closed_at,
    r.last_checked,
    r.posted_on,
    r.level_view,
    r.job_key,
    r.pick_rank,
    first_value(r.id) OVER (PARTITION BY r.job_key ORDER BY r.pick_rank) AS kept_id,
    pp.skill_tiers,
    pp.enrollment,
    pp.role_kind,
    pp.work_signals
   FROM ranked r
     JOIN postings pp ON pp.id = r.id;
create or replace view public.chance_calibration with (security_invoker=true) as  SELECT
        CASE
            WHEN chance < 0.01::double precision THEN '0-1%'::text
            WHEN chance < 0.02::double precision THEN '1-2%'::text
            WHEN chance < 0.05::double precision THEN '2-5%'::text
            WHEN chance < 0.10::double precision THEN '5-10%'::text
            WHEN chance < 0.20::double precision THEN '10-20%'::text
            WHEN chance < 0.40::double precision THEN '20-40%'::text
            ELSE '40%+'::text
        END AS bucket,
    count(*) AS applications,
    count(*) FILTER (WHERE outcome IS NOT NULL) AS answered,
    round(avg(chance)::numeric, 4) AS mean_predicted,
    round(count(*) FILTER (WHERE outcome = 'interview'::text)::numeric / NULLIF(count(*) FILTER (WHERE outcome IS NOT NULL), 0)::numeric, 4) AS interview_rate,
    model
   FROM chance_snapshots
  GROUP BY (
        CASE
            WHEN chance < 0.01::double precision THEN '0-1%'::text
            WHEN chance < 0.02::double precision THEN '1-2%'::text
            WHEN chance < 0.05::double precision THEN '2-5%'::text
            WHEN chance < 0.10::double precision THEN '5-10%'::text
            WHEN chance < 0.20::double precision THEN '10-20%'::text
            WHEN chance < 0.40::double precision THEN '20-40%'::text
            ELSE '40%+'::text
        END), model;
create or replace view public.data_requirements_status with (security_invoker=true) as  SELECT r.id,
    r.priority,
    r.area,
    r.requirement,
    r.assignee,
    r.target_table,
    r.target_metric,
    r.target_fields,
    r.method,
    r.sources,
    r.why,
    r.notes,
    COALESCE(
        CASE
            WHEN r.target_table = 'postings'::text THEN ( SELECT count(*) AS count
               FROM postings)
            ELSE r.target_rows::bigint
        END, 0::bigint) AS target_rows,
    c.rows_collected,
    GREATEST(COALESCE(
        CASE
            WHEN r.target_table = 'postings'::text THEN ( SELECT count(*) AS count
               FROM postings)
            ELSE r.target_rows::bigint
        END, 0::bigint) - c.rows_collected, 0::bigint) AS rows_missing,
        CASE
            WHEN r.target_table IS NULL THEN 'manual'::text
            WHEN c.rows_collected = 0 THEN 'open'::text
            WHEN c.rows_collected >= COALESCE(
            CASE
                WHEN r.target_table = 'postings'::text THEN ( SELECT count(*) AS count
                   FROM postings)
                ELSE r.target_rows::bigint
            END, 0::bigint) THEN 'done'::text
            ELSE 'in progress'::text
        END AS state
   FROM data_requirements r
     CROSS JOIN LATERAL ( SELECT
                CASE r.target_table
                    WHEN 'platform_observations'::text THEN ( SELECT count(*) AS count
                       FROM platform_observations o
                      WHERE r.target_metric IS NULL OR (o.metric = ANY (string_to_array(r.target_metric, ','::text))))
                    WHEN 'intern_pay_observations'::text THEN ( SELECT count(*) AS count
                       FROM intern_pay_observations)
                    WHEN 'study_effects'::text THEN ( SELECT count(*) AS count
                       FROM study_effects)
                    WHEN 'market_tightness'::text THEN ( SELECT count(*) AS count
                       FROM market_tightness)
                    WHEN 'skill_aliases'::text THEN ( SELECT count(*) AS count
                       FROM skill_aliases)
                    WHEN 'requirement_labels'::text THEN ( SELECT count(DISTINCT requirement_labels.posting_id) AS count
                       FROM requirement_labels)
                    WHEN 'fit_ratings'::text THEN ( SELECT count(*) AS count
                       FROM fit_ratings)
                    WHEN 'postings'::text THEN ( SELECT count(*) AS count
                       FROM postings
                      WHERE postings.requirements IS NOT NULL)
                    ELSE 0::bigint
                END AS rows_collected) c
  ORDER BY r.priority, r.id;
create or replace view public.active_jobs with (security_invoker=true) as  SELECT id,
    employer,
    employer_display,
    ats,
    source,
    title,
    region,
    cat,
    cbs_group,
    url,
    ind_sponsor,
    ind_sponsor_name,
    years_min,
    dutch_required OR COALESCE(dutch_jev, 0::real) >= 0.8::double precision AS dutch_required,
    visa_mention,
    junior_title,
    degree_asked,
    skills,
    pay_posted,
    applicants,
    applicants_text,
    valid_through,
    seniority,
    posted_at,
    posted_on,
    fetched_at,
    last_checked,
    level_view AS level,
    level_jev,
    level_conf,
    usable,
    industry,
    workplace,
    job_type,
    dutch_jev,
    family,
        CASE
            WHEN posted_on IS NOT NULL THEN CURRENT_DATE - posted_on
            ELSE days_open
        END AS days_open,
    title_clean,
    closed_at,
    level_view,
    job_key,
    kept_id,
    pick_rank,
        CASE
            WHEN
            CASE
                WHEN posted_on IS NOT NULL THEN CURRENT_DATE - posted_on
                ELSE days_open
            END <= 6 THEN 'fresh'::text
            WHEN
            CASE
                WHEN posted_on IS NOT NULL THEN CURRENT_DATE - posted_on
                ELSE days_open
            END <= 44 THEN 'active'::text
            ELSE 'aging'::text
        END AS freshness_state,
    skill_tiers,
    enrollment,
    role_kind
   FROM app_jobs a
  WHERE pick_rank = 1;
create or replace view public.employer_data_status with (security_invoker=true) as  WITH e AS (
         SELECT app_jobs.employer,
            max(app_jobs.employer_display) AS display,
            count(*) AS open_jobs
           FROM app_jobs
          WHERE app_jobs.closed_at IS NULL
          GROUP BY app_jobs.employer
        ), c AS (
         SELECT e.employer,
            e.display,
            e.open_jobs,
            ( SELECT count(*) AS count
                   FROM job_people x
                  WHERE x.employer = e.employer) AS people,
            (EXISTS ( SELECT 1
                   FROM employer_facts x
                  WHERE x.employer = e.employer)) AS has_facts,
            (EXISTS ( SELECT 1
                   FROM employer_facts x
                  WHERE x.employer = e.employer AND x.logo IS NOT NULL)) AS has_logo,
            (EXISTS ( SELECT 1
                   FROM employer_about x
                  WHERE x.employer = e.employer AND COALESCE(x.about, ''::text) <> ''::text)) AS has_about,
            (EXISTS ( SELECT 1
                   FROM employer_headcount x
                  WHERE x.employer = e.employer)) AS has_headcount,
            (EXISTS ( SELECT 1
                   FROM employer_teams x
                  WHERE x.employer = e.employer)) AS has_teams,
            (EXISTS ( SELECT 1
                   FROM employer_culture x
                  WHERE x.employer = e.employer)) AS has_culture,
            (EXISTS ( SELECT 1
                   FROM employer_news x
                  WHERE x.employer = e.employer)) AS has_news,
            (EXISTS ( SELECT 1
                   FROM employer_money x
                  WHERE x.employer = e.employer)) AS has_money,
            (EXISTS ( SELECT 1
                   FROM employer_ladders x
                  WHERE x.employer = e.employer)) AS has_ladders,
            (EXISTS ( SELECT 1
                   FROM employer_glassdoor x
                  WHERE x.employer = e.employer)) AS has_glassdoor,
            ( SELECT count(*) AS count
                   FROM employer_glassdoor_pay x
                  WHERE x.employer = e.employer) AS glassdoor_pay_rows,
            ( SELECT count(*) AS count
                   FROM employer_glassdoor_position x
                  WHERE x.employer = e.employer) AS glassdoor_positions,
            ( SELECT count(*) AS count
                   FROM employer_glassdoor_pay_report x
                  WHERE x.employer = e.employer) AS glassdoor_pay_reports,
            ( SELECT count(*) AS count
                   FROM employer_glassdoor_reviews x
                  WHERE x.employer = e.employer) AS glassdoor_reviews
           FROM e
        )
 SELECT employer,
    display,
    open_jobs,
    people,
    has_facts,
    has_logo,
    has_about,
    has_headcount,
    has_teams,
    has_culture,
    has_news,
    has_money,
    has_ladders,
    has_glassdoor,
    glassdoor_pay_rows,
    glassdoor_positions,
    glassdoor_pay_reports,
    glassdoor_reviews,
    array_remove(ARRAY[
        CASE
            WHEN people = 0 THEN 'people to contact'::text
            ELSE NULL::text
        END,
        CASE
            WHEN people >= 1 AND people <= 2 THEN 'more people to contact (fewer than 3)'::text
            ELSE NULL::text
        END,
        CASE
            WHEN NOT has_facts THEN 'company facts'::text
            ELSE NULL::text
        END,
        CASE
            WHEN NOT has_logo THEN 'logo'::text
            ELSE NULL::text
        END,
        CASE
            WHEN NOT has_about THEN 'about text'::text
            ELSE NULL::text
        END,
        CASE
            WHEN NOT has_headcount THEN 'headcount'::text
            ELSE NULL::text
        END,
        CASE
            WHEN NOT has_money THEN 'money (revenue, net worth)'::text
            ELSE NULL::text
        END,
        CASE
            WHEN NOT has_glassdoor THEN 'glassdoor overview'::text
            ELSE NULL::text
        END,
        CASE
            WHEN has_glassdoor AND glassdoor_positions = 0 THEN 'glassdoor pay by position'::text
            ELSE NULL::text
        END,
        CASE
            WHEN has_glassdoor AND glassdoor_reviews = 0 THEN 'glassdoor reviews'::text
            ELSE NULL::text
        END], NULL::text) AS missing
   FROM c;
