create or replace view public.employer_hiring with (security_invoker=true) as  SELECT employer,
    open_jobs,
    first_jobs,
    no_dutch_jobs,
    visa_mentions,
    avg_applicants,
    pay_stated,
    ( SELECT COALESCE(jsonb_agg(jsonb_build_object('name', t.c, 'n', t.n) ORDER BY t.n DESC), '[]'::jsonb) AS "coalesce"
           FROM ( SELECT split_part(j.region, ','::text, 1) AS c,
                    count(*) AS n
                   FROM active_jobs j
                  WHERE j.employer = e.employer AND j.region IS NOT NULL AND j.region <> '—'::text
                  GROUP BY (split_part(j.region, ','::text, 1))
                  ORDER BY (count(*)) DESC
                 LIMIT 3) t) AS cities,
    ( SELECT COALESCE(jsonb_agg(jsonb_build_object('name', t.f, 'n', t.n) ORDER BY t.n DESC), '[]'::jsonb) AS "coalesce"
           FROM ( SELECT j.family AS f,
                    count(*) AS n
                   FROM active_jobs j
                  WHERE j.employer = e.employer AND j.family IS NOT NULL AND j.family <> 'Other'::text
                  GROUP BY j.family
                  ORDER BY (count(*)) DESC
                 LIMIT 3) t) AS fields,
    ( SELECT COALESCE(jsonb_agg(jsonb_build_object('name', t.s, 'n', t.n) ORDER BY t.n DESC), '[]'::jsonb) AS "coalesce"
           FROM ( SELECT s.s,
                    count(*) AS n
                   FROM active_jobs j,
                    LATERAL unnest(j.skills) s(s)
                  WHERE j.employer = e.employer
                  GROUP BY s.s
                  ORDER BY (count(*)) DESC
                 LIMIT 5) t) AS skills
   FROM ( SELECT active_jobs.employer,
            count(*) AS open_jobs,
            count(*) FILTER (WHERE active_jobs.level = ANY (ARRAY['Internship'::text, 'Entry'::text])) AS first_jobs,
            count(*) FILTER (WHERE NOT active_jobs.dutch_required) AS no_dutch_jobs,
            count(*) FILTER (WHERE active_jobs.visa_mention) AS visa_mentions,
            round(avg(NULLIF(NULLIF(regexp_replace(COALESCE(active_jobs.applicants::text, ''::text), '[^0-9]'::text, ''::text, 'g'::text), ''::text)::numeric, 0::numeric)))::integer AS avg_applicants,
            count(*) FILTER (WHERE active_jobs.pay_posted IS NOT NULL) AS pay_stated
           FROM active_jobs
          GROUP BY active_jobs.employer) e;
create or replace view public.active_internship_entry_candidates with (security_invoker=true) as  SELECT a.id,
    a.employer,
    a.employer_display,
    a.ats,
    a.source,
    a.title,
    a.region,
    a.cat,
    a.cbs_group,
    a.url,
    a.ind_sponsor,
    a.ind_sponsor_name,
    a.years_min,
    a.dutch_required,
    a.visa_mention,
    a.junior_title,
    a.degree_asked,
    a.skills,
    a.pay_posted,
    a.applicants,
    a.applicants_text,
    a.valid_through,
    a.seniority,
    a.posted_at,
    a.posted_on,
    a.fetched_at,
    a.last_checked,
    a.level,
    a.level_jev,
    a.level_conf,
    a.usable,
    a.industry,
    a.workplace,
    a.job_type,
    a.dutch_jev,
    a.family,
    a.days_open,
    COALESCE(c.qualified_candidate_count, 0) AS validated_candidate_count,
    COALESCE(c.qualified_linkedin_profile_count, 0) AS validated_linkedin_profile_count,
    COALESCE(c.qualified_candidates, '[]'::jsonb) AS validated_candidates
   FROM active_internship_entry a
     LEFT JOIN LATERAL ( SELECT count(*)::integer AS qualified_candidate_count,
            count(DISTINCT cp.canonical_linkedin_url)::integer AS qualified_linkedin_profile_count,
            jsonb_agg(DISTINCT jsonb_build_object('evidence_id', e.id, 'candidate_profile_id', e.candidate_profile_id, 'linkedin_url', cp.canonical_linkedin_url, 'public_identifier', cp.public_identifier, 'headline', cp.headline, 'current_position', cp.current_position, 'status', e.status, 'confidence', e.confidence, 'validation_status', e.validation_status, 'observed_at', e.observed_at)) FILTER (WHERE e.id IS NOT NULL) AS qualified_candidates
           FROM job_candidate_evidence e
             JOIN candidate_profiles cp ON cp.id = e.candidate_profile_id
          WHERE e.posting_id = a.id AND e.validation_status = 'validated'::text AND (e.status = ANY (ARRAY['exact'::text, 'adjacent'::text]))) c ON true;
create or replace view public.active_internship_entry_english with (security_invoker=true) as  SELECT id,
    employer,
    employer_display,
    ats,
    source,
    title,
    region,
    cat,
    cbs_group,
    url,
    ind_sponsor,
    ind_sponsor_name,
    years_min,
    dutch_required,
    visa_mention,
    junior_title,
    degree_asked,
    skills,
    pay_posted,
    applicants,
    applicants_text,
    valid_through,
    seniority,
    posted_at,
    posted_on,
    fetched_at,
    last_checked,
    level,
    level_jev,
    level_conf,
    usable,
    industry,
    workplace,
    job_type,
    dutch_jev,
    family,
    days_open,
    title_clean,
    closed_at,
    level_view,
    job_key,
    kept_id,
    pick_rank,
    freshness_state,
    skill_tiers,
    enrollment,
    role_kind
   FROM active_internship_entry
  WHERE NOT dutch_required;
create or replace view public.active_internship_entry_english_outreach with (security_invoker=true) as  SELECT a.id AS posting_id,
    a.title AS posting_title,
    a.employer AS posting_employer,
    c.id,
    c.employer,
    c.posting_ids,
    c.contact_name,
    c.contact_type,
    c.profile_url,
    c.source_url,
    c.headline,
    c.location,
    c.avatar_url,
    c.about,
    c.experience,
    c.contact_channels,
    c.source_snapshot,
    c.raw_data,
    c.evidence,
    c.confidence,
    c.captured_at,
    COALESCE(c.raw_data ->> 'matching_scope'::text,
        CASE
            WHEN c.contact_type = 'job_listed_contact'::text THEN 'vacancy'::text
            ELSE 'employer'::text
        END) AS matching_scope
   FROM active_internship_entry_english a
     JOIN outreach_contacts c ON a.id = ANY (c.posting_ids);
create or replace view public.active_internship_entry_english_people_coverage with (security_invoker=true) as  SELECT a.id AS posting_id,
    a.employer,
    a.title,
    a.url,
    a.posted_at,
    count(c.id) AS contact_record_count,
    count(c.id) FILTER (WHERE c.contact_type = 'job_listed_contact'::text) AS named_vacancy_contact_count,
    count(c.id) FILTER (WHERE c.contact_type = 'likely_outreach_contact'::text) AS possible_outreach_lead_count,
        CASE
            WHEN count(c.id) FILTER (WHERE c.contact_type = 'job_listed_contact'::text) > 0 THEN 'named_vacancy_contact'::text
            WHEN count(c.id) > 0 THEN 'possible_outreach_lead'::text
            ELSE 'missing_contact'::text
        END AS coverage_status
   FROM active_internship_entry_english a
     LEFT JOIN outreach_contacts c ON a.id = ANY (c.posting_ids)
  GROUP BY a.id, a.employer, a.title, a.url, a.posted_at;

